+/* cxref: a C symbol and its transitive callees, extracted into /xref/ */
+#define XREF_BUDGET 200			/* definitions one closure may hold */
+#define XREF_SPAN 8			/* lines a definition's header may span */
+#define XREF_BODY 2000			/* lines a definition's body may hold */
+
+/* column 0 is what a definition owns and a call site or a member never has:
+ * a function, a macro, an aggregate, a typedef, an object, in that order */
+static char xref_defpat[] =
+	"^[A-Za-z_][^=;]*\\<%s\\>[ \t]*\\([^;]*(?:\\{|$)|"
+	"^%s[ \t]*\\([^;]*(?:\\{|$)|"
+	"^[ \t]*#[ \t]*define[ \t]+%s\\>|"
+	"^(?:typedef[ \t]+)?(?:struct|union|enum)[ \t]+%s\\>[ \t]*\\{?[ \t]*$|"
+	"^typedef\\>[^\\(\\)]*\\<%s\\>[^\\(\\)]*;|"
+	"^[A-Za-z_][^\\(\\)=;]*\\<%s\\>[^\\(\\)=;]*[=;]";
+/* every name a body writes: a call, a type, a global. what it is only the
+ * resolver knows, and a name that no definition owns costs it one lookup */
+static char xref_namepat[] = "\\<[A-Za-z_][A-Za-z0-9_]*";
+/* reserved, so never a definition and cheaper to drop than to look up */
+static char *xref_kwds[] = {"if", "else", "for", "while", "do", "switch",
+	"case", "default", "return", "sizeof", "break", "continue", "goto",
+	"typedef", "struct", "union", "enum", "static", "extern", "const",
+	"volatile", "register", "inline", "restrict", "signed", "unsigned",
+	"void", "char", "short", "int", "long", "float", "double", "defined"};
+
+/* what a statement opens with, so the name behind one is an expression's
+ * and not, the way a type's is, the name a declaration introduces */
+static char *xref_ctls[] = {"if", "else", "while", "do", "switch", "case",
+	"default", "return", "break", "continue", "goto", "sizeof", "defined"};
+
+static int xref_inlist(char **list, int n, char *sym, int len)
+{
+	int i;
+	for (i = 0; i < n; i++)
+		if (!strncmp(list[i], sym, len) && !list[i][len])
+			return 1;
+	return 0;
+}
+
+static int xref_kwd(char *sym, int len)
+{
+	return xref_inlist(xref_kwds, LEN(xref_kwds), sym, len);
+}
+
+static int xref_ctl(char *sym, int len)
+{
+	return xref_inlist(xref_ctls, LEN(xref_ctls), sym, len);
+}
+
+/* the length of s, a buffer line, with its trailing blanks cut off */
+static int xref_rtrim(char *s)
+{
+	int i = lbuf_s(s)->len;
+	for (; i > 0 && uc_isspace(s[i-1]); i--);
+	return i;
+}
+
+static int xref_indent(char *s)
+{
+	int i = 0;
+	for (; s[i] == ' ' || s[i] == '\t'; i++);
+	return i;
+}
+
+/* s with its comments and literals blanked out, so that a name written in
+ * one is never read as a call; state carries a comment across lines */
+static char *xref_code(char *s, int *state)
+{
+	static sbuf *sb;
+	int i;
+	if (!sb)
+		sbuf_make(sb, 256)
+	sbuf_cut(sb, 0)
+	for (i = 0; s[i] && s[i] != '\n'; i++) {
+		switch (*state) {
+		case 0:
+			if (s[i] == '/' && s[i+1] == '/')
+				goto out;
+			else if (s[i] == '/' && s[i+1] == '*')
+				*state = 1;
+			else if (s[i] == '"')
+				*state = 2;
+			else if (s[i] == '\'')
+				*state = 3;
+			else {
+				sbuf_chr(sb, s[i])
+				continue;
+			}
+			break;
+		case 1:
+			if (s[i] == '*' && s[i+1] == '/') {
+				*state = 0;
+				sbuf_chr(sb, ' ')
+				i++;
+			}
+			break;
+		default:
+			if (s[i] == '\\' && s[i+1]) {
+				sbuf_chr(sb, ' ')
+				i++;
+			} else if (s[i] == (*state == 2 ? '"' : '\''))
+				*state = 0;
+		}
+		sbuf_chr(sb, ' ')
+	}
+	out:
+	if (*state > 1)			/* a literal ends with its line */
+		*state = 0;
+	sbufn_ret(sb, sb->s)
+}
+
+/* the '{' or the ';' that ends the header at line, whichever comes first */
+static int xref_brace(struct lbuf *lb, int line, int *brow)
+{
+	char *s;
+	int i, n = lbuf_len(lb);
+	for (i = line; i < n && i < line + XREF_SPAN; i++) {
+		for (s = lbuf_get(lb, i); *s != '\n'; s++) {
+			if (*s == '{') {
+				*brow = i;
+				return 1;
+			}
+			if (*s == ';')
+				return 0;
+		}
+	}
+	return 0;
+}
+
+/* the last line of the body that opens at brow, its braces counted on code
+ * alone: the ones in strings and in comments are not the definition's */
+static int xref_body(struct lbuf *lb, int brow, int *end)
+{
+	char *s;
+	int row, n = lbuf_len(lb), depth = 0, open = 0, state = 0;
+	for (row = brow; row < n && row < brow + XREF_BODY; row++) {
+		for (s = xref_code(lbuf_get(lb, row), &state); *s; s++) {
+			open |= *s == '{';
+			depth += (*s == '{') - (*s == '}');
+		}
+		if (open && depth <= 0) {
+			*end = row;
+			return 0;
+		}
+	}
+	return 1;
+}
+
+/* the last line of the definition at line: a body, a macro, or a statement */
+static int xref_bound(struct lbuf *lb, int line, int *end)
+{
+	char *s = lbuf_get(lb, line);
+	int row, i, n = lbuf_len(lb), brow;
+	if (!s)
+		return 1;
+	if (s[xref_indent(s)] == '#') {		/* a macro runs to its last \ */
+		for (row = line; row < n - 1; row++) {
+			i = xref_rtrim(lbuf_get(lb, row));
+			if (!i || lbuf_get(lb, row)[i-1] != '\\')
+				break;
+		}		/* a continuation into a blank line is not one */
+		while (row > line && !xref_rtrim(lbuf_get(lb, row)))
+			row--;
+		*end = row;
+		return 0;
+	}
+	if (xref_brace(lb, line, &brow))	/* a body, or an initializer */
+		return xref_body(lb, brow, end);
+	for (row = line; row < n && row < line + XREF_SPAN; row++)
+		if (strchr(lbuf_get(lb, row), ';')) {
+			*end = row;
+			return 0;
+		}
+	*end = line;
+	return 0;
+}
+
+/* the definition also owns the type and the comment written above it */
+static int xref_head(struct lbuf *lb, int line)
+{
+	char *s;
+	int row = line, i;
+	if (row > 0) {			/* a return type on a line of its own */
+		s = lbuf_get(lb, row - 1);
+		i = xref_rtrim(s);
+		if (i && !xref_indent(s) && !strpbrk(s, "(){};,=#/") &&
+				(uc_isalpha(*s) || *s == '_'))
+			row--;
+	}
+	while (row > 0) {		/* the comment written above it */
+		s = lbuf_get(lb, row - 1);
+		i = xref_indent(s);
+		if (s[i] == '/' && s[i+1] == '/') {
+			row--;
+			continue;
+		}
+		i = xref_rtrim(s);
+		if (i < 2 || s[i-2] != '*' || s[i-1] != '/')
+			break;
+		for (i = row - 1; i >= 0; i--)	/* up to where the block opens */
+			if (strstr(lbuf_get(lb, i), "/*"))
+				break;
+		s = i < 0 ? NULL : lbuf_get(lb, i);
+		/* a comment the code above trails is that code's, not this
+		 * definition's: only one that opens a line is written for it */
+		if (!s || s[xref_indent(s)] != '/')
+			break;
+		row = i;
+		break;
+	}
+	return row;
+}
+
+/* the definition pattern with every %s expanded to sym */
+static char *xref_pat(char *sym)
+{
+	char *s = xref_defpat;
+	sbuf_smake(sb, 256)
+	for (; *s; s++) {
+		if (s[0] == '%' && s[1] == 's') {
+			sbuf_str(sb, sym)
+			s++;
+		} else
+			sbuf_chr(sb, *s)
+	}
+	sbufn_ret(sb, sb->s)
+}
+
+/* the definition of sym, as a line in the buffer this leaves current. from,
+ * the file the call was read in, is searched first, so a static definition
+ * beats a global one elsewhere, which is what C scoping means here */
+static int xref_resolve(char *sym, char *from, int *outline)
+{
+	char *pat = xref_pat(sym), *path;
+	struct lbuf *ls = tempbufs[1].lb;
+	rset *rs = rset_smake(pat, 0);
+	int i, n = lbuf_len(ls), len, row, off, beg = 0, ret = 0, bs;
+	free(pat);
+	if (!rs)
+		return 0;
+	for (i = 0; i < n; i++) {	/* ex_edit drops the "./" the listing has */
+		path = ls->ln[i];
+		len = lbuf_s(path)->len;
+		if (path[0] == '.' && path[1] == '/')
+			path += 2, len -= 2;
+		if (!strncmp(path, from, len) && !from[len]) {
+			beg = i;
+			break;
+		}
+	}
+	preserve(int, xgrp, xgrp = 0;)	/* the search is ours, not the user's */
+	for (i = 0; i < n && !ret; i++) {
+		path = ls->ln[(beg + i) % n];
+		len = lbuf_s(path)->len;
+		path[len] = '\0';
+		if (syn_filetype(path) == FT(c)) {
+			ex_edit(path, len);
+			for (row = 0; row < lbuf_len(xb); row++) {
+				off = 0;
+				if (lbuf_search(xb, rs, +1, row, lbuf_len(xb),
+							-1, 1, &row, &off))
+					break;
+				/* a line the one above continues into is a
+				 * macro's body, never a definition of its own,
+				 * and extern names one written elsewhere */
+				bs = row ? xref_rtrim(lbuf_get(xb, row - 1)) : 0;
+				if ((!bs || lbuf_get(xb, row - 1)[bs-1] != '\\') &&
+						strncmp(lbuf_get(xb, row), "extern ", 7)) {
+					ret = 1;
+					break;
+				}
+			}
+		}
+		path[len] = '\n';
+	}
+	restore(xgrp)
+	rset_free(rs);
+	if (ret)
+		*outline = row;
+	return ret;
+}
+
+static int xref_seen(sbuf *seen, char *sym, int len)
+{
+	char *s = seen->s, *e, *lim = seen->s + seen->s_n;
+	while (s < lim && (e = memchr(s, '\n', lim - s))) {
+		if (e - s == len && !memcmp(s, sym, len))
+			return 1;
+		s = e + 1;
+	}
+	return 0;
+}
+
+/* a queue entry is the symbol and the file it was read in */
+static void xref_push(sbuf *queue, sbuf *seen, char *sym, int len)
+{
+	sbuf_mem(seen, sym, len)
+	sbuf_chr(seen, '\n')
+	sbuf_mem(queue, sym, len)
+	sbuf_chr(queue, '\t')
+	sbuf_str(queue, xb_path)
+	sbuf_chr(queue, '\n')
+}
+
+static rset *xref_nrs(void)
+{
+	static rset *rs;
+	if (!rs)
+		rs = rset_smake(xref_namepat, 0);
+	return rs;
+}
+
+/* the names an extent declares: a parameter, a local, a member. a declaration
+ * is two names in a row and the second one is the declared, which C scoping
+ * says the body means, not whatever else the tree happens to call that */
+static void xref_locals(struct lbuf *lb, int b, int e, sbuf *loc)
+{
+	rset *rs = xref_nrs();
+	char *s, *p;
+	int grps[4], off, len, i, j, prev, run, state = 0;
+	if (!rs)
+		return;
+	for (i = b; i <= e; i++) {
+		if (!lbuf_get(lb, i))
+			break;
+		s = xref_code(lbuf_get(lb, i), &state);
+		prev = -1;
+		for (off = 0; rset_find(rs, s + off, grps, off ? REG_NOTBOL : 0) >= 0;) {
+			p = s + off + grps[0];
+			len = grps[1] - grps[0];
+			run = prev >= 0;	/* only blanks and stars between */
+			for (j = prev; run && j < p - s; j++)
+				if (s[j] != ' ' && s[j] != '\t' && s[j] != '*')
+					run = 0;
+			for (j = p - s + len; s[j] == ' ' || s[j] == '\t'; j++);
+			/* what a declaration ends with, so a cast, which ends
+			 * with a star, and a call keep the name they name */
+			if (run && s[j] && strchr(",;=[)", s[j])) {
+				sbuf_mem(loc, p, len)
+				sbuf_chr(loc, '\n')
+			}
+			prev = xref_ctl(p, len) ? -1 : p - s + len;
+			off += MAX(grps[1], 1);
+		}
+	}
+}
+
+/* queue every name an extent calls or declares, once each */
+static void xref_scan(struct lbuf *lb, int b, int e, sbuf *queue, sbuf *seen)
+{
+	rset *rs = xref_nrs();
+	char *s, *p;
+	int grps[4], off, len, i, j, state = 0;
+	sbuf_smake(loc, 256)
+	if (!rs) {
+		free(loc->s);
+		return;
+	}
+	xref_locals(lb, b, e, loc);
+	for (i = b; i <= e; i++) {
+		if (!lbuf_get(lb, i))
+			break;
+		s = xref_code(lbuf_get(lb, i), &state);
+		for (off = 0; rset_find(rs, s + off, grps, off ? REG_NOTBOL : 0) >= 0;) {
+			p = s + off + grps[0];
+			len = grps[1] - grps[0];
+			for (j = p - s - 1; j >= 0 && (s[j] == ' ' || s[j] == '\t'); j--);
+			/* a member is written behind a '.' or a '->' and is the
+			 * struct's, never a definition of its own */
+			if (j >= 0 && (s[j] == '.' || (s[j] == '>' && j && s[j-1] == '-')))
+				len = 0;
+			if (len > 0 && !xref_kwd(p, len) && !xref_seen(loc, p, len) &&
+					!xref_seen(seen, p, len))
+				xref_push(queue, seen, p, len);
+			off += MAX(grps[1], 1);
+		}
+	}
+	free(loc->s);
+}
+
+/* extract sym and its callees down to maxdepth (0 is unlimited) into /xref/ */
+static char *xref_build(char *sym, int maxdepth)
+{
+	sbuf *cur, *nxt, *seen, *done, *out, *tmp;
+	struct lbuf *lb;
+	struct buf *obuf = ex_buf;
+	char key[1024], nbuf[32], *s, *e, *from;
+	int start, end, depth, i, n = 0;
+	if (!lbuf_len(tempbufs[1].lb))
+		return "xref: no listing, run :fd";
+	/* resolution may reload this very buffer, which reads the position back
+	 * out of it: save the live one first, or the cursor returns to a stale */
+	exbuf_save(ex_buf)
+	sbuf_make(cur, 256)
+	sbuf_make(nxt, 256)
+	sbuf_make(seen, 256)
+	sbuf_make(done, 256)
+	sbuf_make(out, 4096)
+	xref_push(cur, seen, sym, strlen(sym));
+	for (depth = 0; cur->s_n && n < XREF_BUDGET; depth++) {
+		if (maxdepth && depth >= maxdepth)
+			break;		/* 1gx is the seed alone */
+		for (s = cur->s; s < cur->s + cur->s_n; s = e + 1) {
+			if (n >= XREF_BUDGET)
+				break;
+			if (!(e = memchr(s, '\n', cur->s + cur->s_n - s)))
+				break;
+			*e = '\0';
+			from = strchr(s, '\t');
+			*from++ = '\0';
+			if (!xref_resolve(s, from, &start))
+				continue;	/* the resolver is the filter */
+			i = snprintf(key, sizeof(key), "%s:%d", xb_path, start);
+			if (xref_seen(done, key, i) || xref_bound(xb, start, &end))
+				continue;	/* the bounds are the definition's,
+						 * the head only reaches above it */
+			start = xref_head(xb, start);
+			sbuf_mem(done, key, i)
+			sbuf_chr(done, '\n')
+			if (n++)
+				sbuf_chr(out, '\n')
+			sbuf_str(out, xb_path)		/* the header owns its line, */
+			sbuf_chr(out, ':')		/* so the body reads verbatim */
+			sbuf_mem(out, nbuf, (int)(itoa(start + 1, nbuf) - nbuf))
+			sbuf_chr(out, '\n')
+			for (i = start; i <= end; i++)	/* the line and its newline */
+				sbuf_mem(out, lbuf_get(xb, i), lbuf_i(xb, i)->len + 1)
+			xref_scan(xb, start, end, nxt, seen);
+		}
+		tmp = cur;
+		cur = nxt;
+		nxt = tmp;
+		sbuf_cut(nxt, 0)
+	}
+	sbuf_nul4(out)
+	/* resolution opens buffers behind ex_edit's back, which leaves no mtime */
+	for (i = xbufcur - 1; i >= 0 && bufs[i].mtime == -1; i--)
+		ex_bufpostfix(&bufs[i], 1);
+	if (ex_buf != obuf) {		/* resolution browses, gx does not jump */
+		exbuf_save(ex_buf)
+		ex_buf = obuf;
+		exbuf_load(ex_buf)
+		syn_setft(xb_ft);
+	}
+	lb = tempbufs[XREF_BUF].lb;
+	s = NULL;
+	if (n) {			/* the closure replaces the buffer whole */
+		lbuf_edit(lb, out->s, 0, lbuf_len(lb), 0, 0);
+		temp_pos(XREF_BUF, 0, 0, 0);
+	} else				/* nothing found, so nothing is replaced */
+		s = "xref: no definition";
+	sbuf_free(cur)
+	sbuf_free(nxt)
+	sbuf_free(seen)
+	sbuf_free(done)
+	sbuf_free(out)
+	return s;
+}
